from functools import lru_cache

def count_good_plans(n, m, b, mod, a):
    @lru_cache(None)
    def dp(i, lines_left, bugs_left):
        if lines_left == 0:
            return 1 if bugs_left <= b else 0
        if i >= n or lines_left < 0 or bugs_left < 0:
            return 0
        result = 0
        for j in range(lines_left // a[i] + 1):
            result += dp(i + 1, lines_left - j * a[i], bugs_left - j * a[i])
            result %= mod
        return result

    return dp(0, m, b)

