    dp = [[[-1] * (b + 1) for _ in range(m + 1)] for _ in range(1 << n)]

    def dfs(mask: int, lines_written: int, current_bugs: int) -> int:
        if mask == (1 << n) - 1:
            return 1 if lines_written == m and current_bugs <= b else 0
        if dp[mask][lines_written][current_bugs] != -1:
            return dp[mask][lines_written][current_bugs]

        total_ways = 0
        for i in range(n):
            if not (mask & (1 << i)):
